def altezza_avl(r):
    if r is None:
        return -1
    h_s = altezza_avl(r.left)
    if h_s == -2:
        return -2
    h_d = altezza_avl(r.right)
    if h_d == -2:
        return -2
    if abs(h_s - h_d) > 1:
        return -2
    return 1 + max(h_s, h_d)

def conta_sbilanciati(r):
    h, c = conta_rec(r)
    return c

def conta_rec(r):
    if r is None:
        return -1, 0
    h_s, c_s = conta_rec(r.left)
    h_d, c_d = conta_rec(r.right)
    c = c_s + c_d
    if abs(h_s - h_d) > 1:
        c = c + 1
    return 1 + max(h_s, h_d), c

def is_avl(r):
    ok, h = verifica(r, None, None)
    return ok

def verifica(r, lo, hi):
    if r is None:
        return True, -1
    if (lo is not None and r.chiave <= lo) or (hi is not None and r.chiave >= hi):
        return False, 0
    ok_s, h_s = verifica(r.fsin, lo, r.chiave)
    if not ok_s:
        return False, 0
    ok_d, h_d = verifica(r.fdes, r.chiave, hi)
    if not ok_d:
        return False, 0
    return abs(h_s - h_d) <= 1, 1 + max(h_s, h_d)
